#define main original_main
#include "../../mpc-cuda/main.cu"
#undef main
#include <vector>
#include <fstream>
#include <iomanip>
#define C(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA%s:%d\n",cudaGetErrorString(e),__LINE__);return 2;}}while(0)
using U=unsigned long long;
int main(){cudaDeviceProp p;C(cudaGetDeviceProperties(&p,0));cudaFuncAttributes a,b;C(cudaFuncGetAttributes(&a,MPCcompress));C(cudaFuncGetAttributes(&b,MPCdecompress));int oc,od;C(cudaOccupancyMaxActiveBlocksPerMultiprocessor(&oc,MPCcompress,1024,0));C(cudaOccupancyMaxActiveBlocksPerMultiprocessor(&od,MPCdecompress,1024,0));printf("RESOURCE SM%d blocks%d compregs%d decregs%d compshared%zu decshared%zu compresident%d decresident%d\n",p.multiProcessorCount,p.multiProcessorCount*2,a.numRegs,b.numRegs,a.sharedSizeBytes,b.sharedSizeBytes,oc,od);std::ofstream meta("diagnostic_cases.jsonl");for(int n: {1024,1,63,64,65,1023})for(int dim=1;dim<=32;dim++){if(n!=1024&&dim!=1)continue;std::vector<U>input(n);U seed=0x8f39c7324d895f9bULL;for(int i=0;i<n;i++){seed^=seed<<13;seed^=seed>>7;seed^=seed<<17;input[i]=seed;}int capacity=n+1+(n+63)/64,blocks=p.multiProcessorCount*2;long *in,*out,*decoded;int*off;C(cudaMalloc(&in,n*8));C(cudaMalloc(&out,(capacity+1024)*8));C(cudaMalloc(&decoded,(n+16)*8));C(cudaMalloc(&off,blocks*4));C(cudaMemcpy(in,input.data(),n*8,cudaMemcpyHostToDevice));C(cudaMemset(out,0xa5,(capacity+1024)*8));C(cudaMemset(off,255,blocks*4));MPCcompress<<<blocks,1024>>>(n,in,out,off,dim);C(cudaGetLastError());C(cudaDeviceSynchronize());std::vector<U>encoded(capacity+1024);C(cudaMemcpy(encoded.data(),out,encoded.size()*8,cudaMemcpyDeviceToHost));U count=encoded[0]>>32;int corrupt=0;for(int i=capacity;i<capacity+1024;i++)corrupt+=encoded[i]!=0xa5a5a5a5a5a5a5a5ULL;std::string prefix="case_n"+std::to_string(n)+"_dim"+std::to_string(dim);std::ofstream(prefix+"_input.bin",std::ios::binary).write((char*)input.data(),n*8);std::ofstream(prefix+"_encoded_guarded.bin",std::ios::binary).write((char*)encoded.data(),encoded.size()*8);encoded[0]=(U(n)<<32)+(0x43504d00-1)+dim;C(cudaMemcpy(out,encoded.data(),8,cudaMemcpyHostToDevice));C(cudaMemset(off,255,blocks*4));C(cudaMemset(decoded,0xa5,(n+16)*8));MPCdecompress<<<blocks,1024>>>(out,decoded,off);C(cudaGetLastError());C(cudaDeviceSynchronize());std::vector<U>answer(n+16);C(cudaMemcpy(answer.data(),decoded,answer.size()*8,cudaMemcpyDeviceToHost));int mismatches=0;for(int i=0;i<n;i++)mismatches+=answer[i]!=input[i];std::ofstream(prefix+"_decoded_guarded.bin",std::ios::binary).write((char*)answer.data(),answer.size()*8);meta<<"{\"n\":"<<n<<",\"dim\":"<<dim<<",\"source_capacity_words\":"<<capacity<<",\"actual_compressed_count\":"<<count<<",\"logical_right_guard_words_changed\":"<<corrupt<<",\"full_decoded_word_mismatches\":"<<mismatches<<"}\n";printf("CASE n%d dim%d capacity%d count%llu guard%d mismatch%d\n",n,dim,capacity,count,corrupt,mismatches);C(cudaFree(in));C(cudaFree(out));C(cudaFree(decoded));C(cudaFree(off));}}
